'use client'

import { useState } from 'react'
import { PRODUCT_CATEGORIES, type ProductInput } from '@/lib/vendor/catalog'
import { ImageUploader } from './ImageUploader'
import { VariantEditor } from './VariantEditor'

interface Props { initialValue: ProductInput; submitLabel: string; onSubmit: (input: ProductInput) => Promise<void>; locked?: boolean }
export function ProductForm({ initialValue, submitLabel, onSubmit, locked = false }: Props) {
  const [value, setValue] = useState(initialValue)
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [isSaving, setIsSaving] = useState(false)
  function update(field: keyof ProductInput, next: string | number) { setValue((current) => ({ ...current, [field]: next })); setErrors((current) => ({ ...current, [field]: '' })) }
  async function handleSubmit(event: React.FormEvent) { event.preventDefault(); setIsSaving(true); try { await onSubmit(value) } catch { setErrors({ form: 'We could not save this product. Please try again.' }) } finally { setIsSaving(false) } }
  return <form className="product-form" onSubmit={handleSubmit} noValidate><div className="product-form-grid"><label className="vendor-field"><span>Product name<b>*</b></span><input disabled={locked} value={value.name} onChange={(event) => update('name', event.target.value)} aria-invalid={Boolean(errors.name)} placeholder="e.g. Rhea three-seater sofa" />{errors.name ? <small className="vendor-field-error">{errors.name}</small> : null}</label><label className="vendor-field"><span>SKU<b>*</b></span><input disabled={locked} value={value.sku} onChange={(event) => update('sku', event.target.value)} aria-invalid={Boolean(errors.sku)} placeholder="Your unique stock code" />{errors.sku ? <small className="vendor-field-error">{errors.sku}</small> : null}</label><label className="vendor-field"><span>Category<b>*</b></span><select disabled={locked} value={value.category} onChange={(event) => update('category', event.target.value)}><option value="">Choose a category</option>{PRODUCT_CATEGORIES.map((category) => <option value={category} key={category}>{category}</option>)}</select>{errors.category ? <small className="vendor-field-error">{errors.category}</small> : null}</label><label className="vendor-field"><span>Price (INR)<b>*</b></span><input disabled={locked} type="number" min="0" value={value.price || ''} onChange={(event) => update('price', Number(event.target.value))} />{errors.price ? <small className="vendor-field-error">{errors.price}</small> : null}</label><label className="vendor-field"><span>Stock<b>*</b></span><input disabled={locked} type="number" min="0" value={value.stock} onChange={(event) => update('stock', Number(event.target.value))} />{errors.stock ? <small className="vendor-field-error">{errors.stock}</small> : null}</label></div><label className="vendor-field product-description"><span>Description<b>*</b></span><textarea disabled={locked} value={value.description} onChange={(event) => update('description', event.target.value)} rows={5} placeholder="Describe materials, dimensions, care, and what makes this piece useful." />{errors.description ? <small className="vendor-field-error">{errors.description}</small> : null}</label><div className="product-form-section"><p className="vendor-eyebrow">Product media</p>{locked ? <p className="approval-lock-note">Images are locked while this product is under review.</p> : <ImageUploader images={value.images} onChange={(images) => setValue((current) => ({ ...current, images }))} />}</div><div className="product-form-section">{locked ? <p className="approval-lock-note">Variants are locked while this product is under review.</p> : <VariantEditor variants={value.variants} onChange={(variants) => setValue((current) => ({ ...current, variants }))} />}</div>{errors.form ? <p className="vendor-field-error">{errors.form}</p> : null}<div className="product-form-submit"><button type="submit" className="btn-next" disabled={isSaving || locked}>{locked ? 'Locked during review' : isSaving ? 'Saving...' : submitLabel}</button></div></form>
}